#include <iostream>

void modifyByPointer(int* ptr) {
    if (ptr != nullptr) {
        *ptr += 10; // Dereference operator modifies original value
    }
}

void modifyByReference(int& ref) {
    ref += 20; // Modifies original value directly without pointer syntax
}

int main() {
    int value = 50;
    int* pVal = &value; // & is the address-of operator

    std::cout << "Original Value: " << value << "\n";
    std::cout << "Memory Address: " << pVal << "\n";

    modifyByPointer(pVal);
    std::cout << "After Pointer Modification: " << value << "\n"; // 60

    modifyByReference(value);
    std::cout << "After Reference Modification: " << value << "\n"; // 80

    return 0;
}

#include <iostream>
#include <memory>
#include <vector>

class SensorReading {
private:
    double timestamp;
    double value;
public:
    SensorReading(double ts, double val) : timestamp(ts), value(val) {
        std::cout << "[Allocated] SensorReading at t=" << timestamp << "\n";
    }
    ~SensorReading() {
        std::cout << "[Deallocated] SensorReading at t=" << timestamp << "\n";
    }
    void print() const {
        std::cout << "Reading: " << value << " at " << timestamp << "s\n";
    }
};

int main() {
    std::cout << "--- Entering Scope ---\n";
    {
        // Allocate exclusively-owned heap resource using make_unique
        auto sensor = std::make_unique<SensorReading>(1.042, 98.6);
        sensor->print();

        // Ownership can be transferred, but not duplicated
        std::vector<std::unique_ptr<SensorReading>> pipeline;
        pipeline.push_back(std::move(sensor)); // sensor is now null

        // pipeline automatically cleans up all elements when leaving scope!
    }
    std::cout << "--- Exited Scope (Memory Cleaned Automatically) ---\n";
    return 0;
}

#include <iostream>
#include <memory>

class ModelInferenceEngine {
public:
    // Base class destructor MUST ALWAYS be virtual to ensure
    // derived destructors execute when deleted via base pointer!
    virtual ~ModelInferenceEngine() = default;

    // Pure virtual function (defines an abstract interface)
    virtual void predict(const std::vector<float>& input) = 0;
};

class LightGBMEngine : public ModelInferenceEngine {
public:
    void predict(const std::vector<float>& input) override {
        std::cout << "Executing LightGBM leaf-wise gradient boosted inference\n";
    }
};

class MediaPipeEngine : public ModelInferenceEngine {
public:
    void predict(const std::vector<float>& input) override {
        std::cout << "Executing MediaPipe neural graph landmark inference\n";
    }
};
